namespace sv_ed9d4cda51c84333bb27ea81012e4240.Client.Models;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Description,
    string Location);

using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Models;

namespace sv_ed9d4cda51c84333bb27ea81012e4240.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Models;
using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Services;

namespace sv_ed9d4cda51c84333bb27ea81012e4240.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new ShipmentDetails(
            TrackingNumber: "TRK-1001",
            Status: "In Transit",
            Location: "Memphis, TN",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 7, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 1, 8, 0, 0, TimeSpan.Zero), "Package picked up", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 2, 14, 30, 0, TimeSpan.Zero), "Arrived at sorting facility", "Newark, NJ"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 3, 6, 15, 0, TimeSpan.Zero), "Departed sorting facility", "Newark, NJ"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 3, 22, 45, 0, TimeSpan.Zero), "Arrived at regional hub", "Memphis, TN"),
            ]),

        ["TRK-1002"] = new ShipmentDetails(
            TrackingNumber: "TRK-1002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 2, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 5, 28, 10, 0, 0, TimeSpan.Zero), "Package picked up", "Seattle, WA"),
                new StatusUpdate(new DateTimeOffset(2026, 5, 29, 16, 0, 0, TimeSpan.Zero), "In transit", "Portland, OR"),
                new StatusUpdate(new DateTimeOffset(2026, 5, 31, 9, 20, 0, TimeSpan.Zero), "Out for delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 5, 31, 14, 5, 0, TimeSpan.Zero), "Delivered — signed by J. Smith", "San Francisco, CA"),
            ]),

        ["TRK-1003"] = new ShipmentDetails(
            TrackingNumber: "TRK-1003",
            Status: "Processing",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 10, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 3, 20, 0, 0, TimeSpan.Zero), "Label created", "Chicago, IL"),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Models;

namespace sv_ed9d4cda51c84333bb27ea81012e4240.Client.Services;

public sealed class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Models
@using sv_ed9d4cda51c84333bb27ea81012e4240.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipments> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <p><em>Loading shipment @TrackingNumber…</em></p>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h4>Status History</h4>
    @if (_shipment.StatusUpdates.Count == 0)
    {
        <p>No status updates yet.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && !_loading)
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        CancelPending();

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        _loadedTrackingNumber = TrackingNumber;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation or disposal) — no UI update needed.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

